valid = {'90':90.0,'  42 ':42.0,'0':0.0,'0007':7.0,'2d':172800.0,'3h':10800.0,'15m':900.0,'45s':45.0,'500ms':0.5,'1h30m':5400.0,'2d4h':187200.0,'1m1s':61.0,'1s500ms':1.5,'1d1h1m1s1ms':90061.001,'1d1ms':86400.001,'90m':5400.0,'1500ms':1.5,'001h030m':5400.0,'0s':0.0,'0ms':0.0,'0d0h0m0s0ms':0.0,' 1h 30m ':5400.0,'\t1h\n30m\r':5400.0,'1h\u200330m':5400.0}
invalid = ['', '   ', '\t\n', '-1', '-1h', '+1', '+1h', '1.5', '1.5h', '1e3s', '1_000s', '1x', '1H', 'h', 'ms', 'abc', '1h1h', '1ms2ms', '0s0s', '30m1h', '1ms1s', '0s0m', '1h30', '30 1h', '1 2', '1h,30m', '1h!', '1 h', '1\th', '1 0s', '1m s', '\u2163', '\u2163h', '\u00bd', '\u00bds', '\u2460', '\u2460h']
for sample, expected in valid.items():
    actual = parse_duration(sample)
    assert isinstance(actual, float) and abs(actual - expected) < 1e-9, (sample, actual)
for sample in invalid:
    try: parse_duration(sample)
    except ValueError: pass
    else: raise AssertionError((sample, 'accepted'))
for sample in (90, None, 1.5, True, b'90', []):
    try: parse_duration(sample)
    except TypeError: pass
    else: raise AssertionError((sample, 'accepted'))
assert direct is parse_duration
print(f'checked {len(valid)} valid, {len(invalid)} invalid, 6 non-string inputs and both import paths')
